import { TagSchema, type Tags } from "./tagging-schema";

export function parseTagText(text: string): Tags {
  let json: unknown;
  try {
    json = JSON.parse(text);
  } catch {
    throw new Error("Tagging response was not JSON");
  }
  return TagSchema.parse(json);
}

export function tagsToItemRow(args: {
  userId: string;
  imageUrl: string;
  cutoutUrl: string | null;
  tags: Tags;
}) {
  const { userId, imageUrl, cutoutUrl, tags } = args;
  return {
    user_id: userId,
    image_url: imageUrl,
    cutout_url: cutoutUrl,
    category: tags.category,
    subcategory: tags.subcategory,
    colors: tags.colors,
    pattern: tags.pattern,
    material: tags.material,
    texture: tags.texture,
    formality: tags.formality,
    seasons: tags.seasons,
  };
}

"use server";

import Anthropic from "@anthropic-ai/sdk";
import { taggingJsonSchema } from "./tagging-schema";
import { parseTagText } from "./parse-tags";

const client = new Anthropic(); // reads ANTHROPIC_API_KEY (server-only)

const PROMPT = `You are an expert menswear cataloguer. Tag the SINGLE item in the photo — a \
garment, a pair of shoes, or an accessory. Its background may be removed. Judge only from what \
is visible and fill every field.

category — the family it belongs to:
  · Tops: shirts, tees, polos, knits, sweaters, hoodies
  · Bottoms: trousers, chinos, jeans, shorts, skirts
  · Outerwear: coats, overcoats, blazers, jackets
  · Shoes: all footwear
  · Accessories: belts, bags, hats, scarves, ties, watches, jewellery, sunglasses
subcategory — the specific type, in menswear vocabulary (e.g. "Oxford shirt", "Chinos", \
"Penny loafers", "Chelsea boots", "Leather belt", "Field watch"). Be precise.
colors — the 1-3 dominant colours, most-dominant first, common names (navy, charcoal, cream, \
tan, olive, burgundy). Ignore small logos and hardware.
pattern — one of: solid, striped, check, print, other.
material — the main material, from this list ONLY: Cotton, Wool, Merino wool, Cashmere, Linen, \
Silk, Denim, Leather, Suede, Faux leather, Canvas, Corduroy, Tweed, Fleece, Shearling, Down, \
Polyester, Acrylic, Nylon, Viscose, Modal, Lyocell, Stainless steel, Gold, Silver, Rubber, Other. \
For a blend, name the DOMINANT fibre. Pick the closest; use Other only if none fit.
texture — how the fabric is BUILT, from this list ONLY: Flat, Ribbed, Cable knit, Waffle, \
Chunky knit, Fine knit, Brushed, Fleece-back, Twill, Herringbone, Quilted, Pile, Open knit, Terry, \
Seersucker, Other. This is separate from material: a ribbed merino knit and a flat merino shirt \
share a material but wear very differently. Use Flat for smooth woven cloth with no visible \
structure, and Other only if none fit.
formality — 1 very casual (tees, sneakers, hoodies) up to 5 formal (suits, dress shoes, silk \
ties). 3 is smart-casual: chinos, oxford shirts, loafers, clean minimal sneakers.
seasons — every season the item genuinely suits (wool coat → Autumn, Winter; linen shirt → \
Spring, Summer; a plain cotton tee → all four).

Return ONLY the structured tags.`;

export async function tagItem(
  cutoutBase64: string,
  mediaType: "image/png" | "image/jpeg" | "image/webp",
) {
  const res = await client.messages.create({
    model: "claude-haiku-4-5",
    max_tokens: 512,
    output_config: { format: { type: "json_schema", schema: taggingJsonSchema } },
    messages: [
      {
        role: "user",
        content: [
          { type: "image", source: { type: "base64", media_type: mediaType, data: cutoutBase64 } },
          { type: "text", text: PROMPT },
        ],
      },
    ],
  });
  const text = res.content.find((b) => b.type === "text")?.text ?? "{}";
  return parseTagText(text); // validated Tags (a draft shown on the confirm screen)
}

import {
  TagSchema,
  MATERIALS as AI_MATERIALS,
  TEXTURES as AI_TEXTURES,
} from "@/lib/ai/tagging-schema";

/**
 * The single source for every closet vocabulary.
 *
 * These lists were previously copy-pasted into confirm-form.tsx and
 * item-detail.tsx, and neither copy matched what the tagger was told to emit —
 * so the AI could write a material the edit screen could not offer back.
 * Categories and seasons are DERIVED from TagSchema so drift is impossible;
 * the rest are defined here and consumed by the schema.
 */

export const CATEGORIES = TagSchema.shape.category.options;
export const SEASONS = TagSchema.shape.seasons.element.options;

export const FORMALITY_LABEL = [
  "",
  "Very casual",
  "Casual",
  "Smart casual",
  "Business",
  "Formal",
] as const;

/**
 * Materials and textures are DEFINED in `lib/ai/tagging-schema.ts` and
 * re-exported here, not the other way round: this module derives CATEGORIES and
 * SEASONS from `TagSchema`, so importing vocab from the schema would be a
 * cycle. Every UI surface still reads them from here, so there is one import
 * path for the whole closet vocabulary.
 */
export const MATERIALS = AI_MATERIALS;
export const TEXTURES = AI_TEXTURES;

export const PATTERNS = ["solid", "striped", "check", "print", "other"] as const;

/**
 * The palette the swatch picker offers. Names match what the tagger emits and
 * what `lib/generator/color.ts` groups into families — a colour the generator
 * cannot place is a colour that silently scores nothing.
 */
export const COLORS = [
  { name: "black", hex: "#141414" },
  { name: "charcoal", hex: "#36353a" },
  { name: "grey", hex: "#8a8a8f" },
  { name: "white", hex: "#f4f1ea" },
  { name: "cream", hex: "#ece3d2" },
  { name: "stone", hex: "#cabfae" },
  { name: "beige", hex: "#d5c4a8" },
  { name: "camel", hex: "#b08d57" },
  { name: "tan", hex: "#a9784f" },
  { name: "brown", hex: "#6b4b32" },
  { name: "rust", hex: "#b86a47" },
  { name: "burgundy", hex: "#5e2733" },
  { name: "olive", hex: "#5e7256" },
  { name: "green", hex: "#3f6b4a" },
  { name: "navy", hex: "#242f45" },
  { name: "blue", hex: "#3d5a80" },
  { name: "denim", hex: "#5a7896" },
  { name: "pink", hex: "#d0a0a0" },
  { name: "yellow", hex: "#d6b756" },
  { name: "silver", hex: "#c0c0c8" },
  { name: "gold", hex: "#c9a227" },
] as const;

export function colorHex(name: string): string | undefined {
  const n = name.toLowerCase();
  return COLORS.find((c) => c.name === n)?.hex;
}

